import { Mesh, PlaneGeometry, Group, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, float, hash } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const palette = {
    background: colors.background ?? '#0b0b10',
    surface: colors.surface ?? '#14141a',
    ink: colors.ink ?? '#16161d',
    paper: colors.paper ?? '#e8ecf2',
    accent: colors.accent ?? '#ff2a38',
  };

  const cBg = new THREE.Color(palette.background);
  const cSurf = new THREE.Color(palette.surface);
  const cAccent = new THREE.Color(palette.accent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const root = new Group();
  root.name = 'editorial-plate';

  const timelines = [];
  const disposables = [];

  // ---- Backdrop plate 7 x 5.5 at z=0 ----
  const plateGeo = new PlaneGeometry(7, 5.5);
  const plateMat = new MeshBasicNodeMaterial();
  plateMat.colorNode = mix(vec3(cSurf), vec3(cBg), uv().y).add(
    hash(uv().mul(float(900.0))).sub(float(0.5)).mul(float(0.015))
  );
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);
  disposables.push({ geometry: plateGeo, material: plateMat });

  // ---- helpers ----
  function collectMaterials(obj) {
    const mats = [];
    obj.traverse((c) => {
      if (c.isMesh && c.material) {
        if (Array.isArray(c.material)) mats.push(...c.material);
        else mats.push(c.material);
      }
    });
    return mats;
  }

  function setOpacity(obj, v) {
    for (const m of collectMaterials(obj)) {
      m.transparent = true;
      m.opacity = v;
      if (m.needsUpdate !== undefined) m.needsUpdate = true;
    }
  }

  function registerText(obj) {
    disposables.push({ obj });
    return obj;
  }

  function riseIn(block, targetY, delay) {
    block.position.y = targetY + 0.4;
    setOpacity(block, 0);
    const proxy = { o: 0 };
    const tl = gsap.timeline({ delay });
    tl.to(block.position, { y: targetY, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(
      proxy,
      { o: 1, duration: 0.7, ease: 'power2.out', onUpdate: () => setOpacity(block, proxy.o) },
      0
    );
    timelines.push(tl);
  }

  const SCALE = 0.005; // px -> scene units (em-height mapping, uniform across roles)
  const X = -3.1;

  // ---- Kicker ----
  const kickerItem = items.find((i) => i.role === 'kicker') || { text: 'NOVA ATELIER / JOURNAL' };
  const kicker = ctx.fontAtlas.createText(kickerItem.text, {
    fontSize: 18,
    color: palette.paper,
    align: 'left',
    letterSpacingPx: 0.12 * 18,
  });
  kicker.scale.setScalar(SCALE);
  kicker.position.set(X, 1.7, 0.03);
  root.add(kicker);
  registerText(kicker);
  riseIn(kicker, 1.7, 0.0);

  // ---- Hero (two stacked lines + letterpress shadow) ----
  const heroItems = items.filter((i) => i.role === 'hero');
  const heroTexts = heroItems.length ? heroItems.map((i) => i.text) : ['PRECISION IS', 'A HABIT.'];
  const heroYs = [0.9, 0.25];
  heroTexts.forEach((line, i) => {
    const g = new Group();

    const main = ctx.fontAtlas.createText(line, {
      fontSize: 124,
      color: palette.paper,
      align: 'left',
      letterSpacingPx: -0.015 * 124,
    });
    main.scale.setScalar(SCALE);
    main.position.set(0, 0, 0.02);
    g.add(main);
    registerText(main);

    const shadow = ctx.fontAtlas.createText(line, {
      fontSize: 124,
      color: palette.ink,
      align: 'left',
      letterSpacingPx: -0.015 * 124,
    });
    shadow.scale.setScalar(SCALE);
    shadow.position.set(0, 0, 0.0); // 0.02 behind main -> letterpress edge
    g.add(shadow);
    registerText(shadow);

    g.position.set(X, heroYs[i] ?? 0.9, 0.03);
    root.add(g);
    riseIn(g, heroYs[i] ?? 0.9, 0.08 + i * 0.08);
  });

  // ---- Accent underline rule (draws after hero lands) ----
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshBasicNodeMaterial();
  ruleMat.colorNode = vec3(cAccent).mul(float(1.2));
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(X + 1.1, -0.15, 0.03);
  rule.scale.x = 0.0001;
  root.add(rule);
  disposables.push({ geometry: ruleGeo, material: ruleMat });
  {
    const tl = gsap.timeline({ delay: 0.9 });
    tl.to(rule.scale, { x: 1, duration: 0.5, ease: 'power3.out' });
    timelines.push(tl);
  }

  // ---- Body ----
  const bodyItem = items.find((i) => i.role === 'body') || {
    text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
  };
  const body = ctx.fontAtlas.createText(bodyItem.text, {
    fontSize: 26,
    color: palette.paper,
    align: 'left',
    maxWidthPx: 4.5 / SCALE,
    letterSpacingPx: 0,
  });
  body.scale.setScalar(SCALE);
  body.position.set(X, -0.8, 0.03);
  root.add(body);
  registerText(body);
  riseIn(body, -0.8, 0.24);

  // ---- Caption ----
  const captionItem = items.find((i) => i.role === 'caption') || { text: 'ISSUE 12 / JULY 2026' };
  const caption = ctx.fontAtlas.createText(captionItem.text, {
    fontSize: 18,
    color: palette.paper,
    align: 'left',
    letterSpacingPx: 0.08 * 18,
  });
  caption.scale.setScalar(SCALE);
  caption.position.set(X, -1.9, 0.03);
  root.add(caption);
  registerText(caption);
  riseIn(caption, -1.9, 0.32);

  // ---- cleanup ----
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => {
      if (d.geometry) d.geometry.dispose();
      if (d.material) d.material.dispose();
      if (d.obj) {
        d.obj.traverse((c) => {
          if (c.isMesh) {
            if (c.geometry) c.geometry.dispose();
            if (c.material) {
              if (Array.isArray(c.material)) c.material.forEach((m) => m.dispose());
              else c.material.dispose();
            }
          }
        });
      }
    });
  };

  root.userData.handlers = {};

  return root;
}
